const generateERPCode = (sapData) => {
    let erpCodesObj = {};
    let erpCodeString = "";

    // filter out the erpcodes from the sap char
    sapData.outputParameters.char_summary_items.filter(el => el.Tab === "Valve Configuration").forEach(el => {
        erpCodesObj[el.SapChar.split("_")[el.SapChar.split("_").length - 1]] = {
            erpCode: el.CharValue
        }
    })

    let erpCodesPositionOnlyObj = {}
    // add the erp positions to each erpCodes
    erpPositionMapping.forEach((el => {
        if (erpCodesObj[el.abbr] && erpCodesObj[el.abbr].erpCode === el.erpCode && el.erpPosition) {
            erpCodesPositionOnlyObj[el.abbr] = {
                erpCode: erpCodesObj[el.abbr].erpCode,
                erpPosition: el.erpPosition
            }
        }
    }))

    // Convert object to array of key-value pairs
    let erpCodesArray = Object.entries(erpCodesPositionOnlyObj);

    // Sort the array based on erpPosition values
    erpCodesArray.sort((a, b) => {
        return parseInt(a[1].erpPosition) - parseInt(b[1].erpPosition);
    });

    // Convert the sorted array back to object
    // erpCodesObj = Object.fromEntries(erpCodesArray);
    erpCodesArray.forEach(item => {
        erpCodeString += item[1].erpCode
    })

    return erpCodeString;
}

const erpCodetableData = (sapData) => {
    let erpCodetableDataArr = [];

    sapData.outputParameters.char_summary_items.filter(el => el.Tab === "Valve Configuration").forEach(el => {
        erpCodetableDataArr.push({
            Code: el.CharValue,
            Category: el.SapCharDesc,
            Description: el.CharValueDesc
        })
    })
    sapData.outputParameters.char_summary_items.filter(el => el.Tab === "Special Requirement").forEach(el => {
        erpCodetableDataArr.push({
            Code: el.CharValue,
            Category: el.SapCharDesc,
            Description: el.CharValueDesc
        })
    })

    // sapData.outputParameters.char_summary_items.filter(el => el.Tab === "Valve Configuration").forEach(el => {
    //     erpPositionMapping.forEach((mappingel => {
    //         if (mappingel.abbr === el.SapChar.split("_")[el.SapChar.split("_").length - 1]) {
    //             erpCodetableDataArr.push({
    //                 Code: el.CharValue,
    //                 Category: el.SapCharDesc,
    //                 Description: el.CharValueDesc,
    //                 erpPosition: parseInt(el.erpPosition)
    //             })
    //         }
    //     }))
    // })

    return erpCodetableDataArr;
}

const getCatalogNumber = (sapData) => {
    if(sapData === null) return "";

    let catalogue_number = "";
    sapData.outputParameters.char_summary_items.forEach(item => {
        if (item.SapChar.includes("CATALOG_NUMBER")) {
            catalogue_number = item.CharValue;
        }
    })
    return catalogue_number;
}

module.exports = {
    generateERPCode,
    erpCodetableData,
    getCatalogNumber
};